create table contactabilidad ( id bigint generated by default as identity constraint xxcontactabilidad_pkey primary key, client_id bigint not null constraint fk_xxcontactabilidad_client_id references m_client, "YesNo_cd_Requiere Visita" integer, "Canal de visita_cd_Canal de visita" integer, "Causal Rechazo Visita_cd_Causal Rechazo Visita" integer, "Observacion Rechazo Visita" text, "Usuario asignado" text, "Correo Usuario Asignado" text, "Fecha Inicio Contactabilidad" text, "Validacion contactabilidad" text, "Causal Rechazo Contactabilidad" text, "Observacion Rechazo Contactabilidad" text, "Observacion Contactabilidad" text, "Segunda Observacion Contactabilidad" text, "Tercera Observacion Contactabilidad" text, "Telefono de Contactabilidad" text, "Fecha Fin Contactabilidad" date, created_at timestamp, updated_at timestamp );
alter table contactabilidad owner to postgres;
create index idx_xxcontactabilidad_client_id on contactabilidad (client_id);


